(window["webpackJsonp"]=window["webpackJsonp"]||[]).push([["pages-user-agreement-privacy"],{"178b":function(n,t,e){"use strict";e.d(t,"b",(function(){return u})),e.d(t,"c",(function(){return r})),e.d(t,"a",(function(){}));var u=function(){var n=this.$createElement,t=this._self._c||n;return t("v-uni-view",[this._v("望诊标注小程序隐私保护指引\n\t本指引是望诊标注小程序开发者 （以下简称“开发者”）为处理你的个人信息而制定。\n\t\n\t开发者处理的信息\n\t根据法律规定，开发者仅处理实现小程序功能所必要的信息。\n\t\n\t为了使用微信登录，开发者将在获取你的明示同意后，收集你的微信昵称、头像。\n\t为了联系用户，开发者将在获取你的明示同意后，收集你的手机号。\n\t开发者 收集你的身份证号码，用于唯一确定用户。\n\t\n\t为了拍摄照片，开发者将在获取你的明示同意后，访问你的摄像头。\n\t你的权益\n\t关于你的个人信息，你可以通过以下方式与开发者联系，行使查阅、复制、更正、删除等法定权利。\n\t\n\t若你在小程序中注册了账号，你可以通过以下方式与开发者联系，申请注销你在小程序中使用的账号。在受理你的申请后，开发者承诺在十五个工作日内完成核查和处理，并按照法律法规要求处理你的相关信息。\n\t\n\t电话:18035154852\n\t\n\t开发者对信息的存储\n\t 开发者承诺，除法律法规另有规定外，开发者对你的信息的保存期限应当为实现处理目的所必要的最短时间。\n\t\n\t信息的使用规则\n\t开发者将会在本指引所明示的用途内使用收集的信息\n\t\n\t如开发者使用你的信息超出本指引目的或合理范围，开发者必须在变更使用目的或范围前，再次以短信方式告知并征得你的明示同意。\n\t\n\t信息对外提供\n\t开发者承诺，不会主动共享或转让你的信息至任何第三方，如存在确需共享或转让时，开发者应当直接征得或确认第三方征得你的单独同意。\n\t\n\t开发者承诺，不会对外公开披露你的信息，如必须公开披露时，开发者应当向你告知公开披露的目的、披露信息的类型及可能涉及的信息，并征得你的单独同意。\n\t\n\t你认为开发者未遵守上述约定，或有其他的投诉建议、或未成年人个人信息保护相关问题，可通过以下方式与开发者联系；或者向微信进行投诉。\n\t电话 : 18035154852\n\t\n\t更新日期：2024-01-15\n\t\n\t生效日期：2024-01-15")])},r=[]},5548:function(n,t,e){"use strict";e.r(t);var u=e("943a"),r=e.n(u);for(var i in u)["default"].indexOf(i)<0&&function(n){e.d(t,n,(function(){return u[n]}))}(i);t["default"]=r.a},"931f":function(n,t,e){"use strict";e.r(t);var u=e("178b"),r=e("5548");for(var i in r)["default"].indexOf(i)<0&&function(n){e.d(t,n,(function(){return r[n]}))}(i);var a=e("f0c5"),c=Object(a["a"])(r["default"],u["b"],u["c"],!1,null,"446693cd",null,!1,u["a"],void 0);t["default"]=c.exports},"943a":function(n,t,e){"use strict";e("7a82"),Object.defineProperty(t,"__esModule",{value:!0}),t.default=void 0;t.default={data:function(){return{}},methods:{}}}}]);